<?php
require_once __DIR__.'/config/config.php';
$q=trim($_GET['q']??'');$type=trim($_GET['type']??'');$where="WHERE d.status='PUBLISHED'";$params=[];
if($q!==''){$where.=' AND (d.title LIKE ? OR d.description LIKE ? OR d.location LIKE ? OR d.source_name LIKE ?)';for($i=0;$i<4;$i++)$params[]="%$q%";}
if($type!==''){$where.=' AND d.media_type=?';$params[]=$type;}
$s=db()->prepare("SELECT d.*,s.title story_title FROM documentaries d LEFT JOIN stories s ON s.id=d.story_id $where ORDER BY COALESCE(d.event_date,'1000-01-01') DESC,d.created_at DESC");$s->execute($params);$documentaries=$s->fetchAll();
function documentary_embed(?string $url): ?string { $parts=parse_url(trim((string)$url));$host=strtolower($parts['host']??'');$path=$parts['path']??'';$query=[];parse_str($parts['query']??'',$query);if(str_ends_with($host,'youtube.com')){if(str_starts_with($path,'/embed/'))return 'https://www.youtube-nocookie.com'.$path;if(isset($query['v'])&&preg_match('/^[A-Za-z0-9_-]{6,20}$/',$query['v']))return 'https://www.youtube-nocookie.com/embed/'.$query['v'];}if($host==='youtu.be'&&preg_match('#^/([A-Za-z0-9_-]{6,20})#',$path,$m))return 'https://www.youtube-nocookie.com/embed/'.$m[1];if(str_ends_with($host,'vimeo.com')&&preg_match('#^/(?:video/)?([0-9]+)#',$path,$m))return 'https://player.vimeo.com/video/'.$m[1];return null;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Explore documentaries, interviews, videos, and recordings preserving Nepal's disaster history and community experiences."><title>Disaster Documentary Archive - Nepal Disaster Archive</title><link rel="canonical" href="<?=e(absolute_url('/documentaries'))?>"><style>:root{--ink:#17202a;--paper:#f7f3ed;--red:#9e2b25;--green:#263d3a;--line:#d9d0c6}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,serif}.nav{position:sticky;top:0;background:#111820;color:#fff;z-index:2;padding:15px 5%;display:flex;align-items:center;gap:25px;font:13px Arial}.nav a{color:#fff;text-decoration:none}.logo{font-weight:900;letter-spacing:2px}.navlinks{margin-left:auto;display:flex;gap:18px}.hero{padding:80px 7% 65px;background:var(--green);color:#fff}.wrap{width:min(1150px,90%);margin:auto}.hero h1{font-size:clamp(44px,7vw,80px);line-height:.95;max-width:900px;margin:15px 0 25px}.hero p{font-size:21px;line-height:1.6;color:#dce4df;max-width:780px}.section{padding:60px 0}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:25px 0}.filters input,.filters select,.filters button{padding:13px;border:1px solid var(--line);border-radius:6px;background:#fff;font:15px Arial}.filters button{background:var(--red);border-color:var(--red);color:#fff;font-weight:700}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}.card{background:#fff;border:1px solid var(--line);border-radius:8px;overflow:hidden}.media{aspect-ratio:16/9;background:#17202a}.media iframe{width:100%;height:100%;border:0}.media img{width:100%;height:100%;object-fit:cover}.card-body{padding:22px}.tag{font:800 12px Arial;color:var(--red);text-transform:uppercase;letter-spacing:1px}.card h2{font-size:28px;margin:10px 0}.card p{color:#555;line-height:1.7}.watch{display:inline-block;color:var(--red);font:700 14px Arial;text-decoration:none;margin-top:8px}.meta{font:13px Arial;color:#68706f}.empty{padding:25px;background:#fff;border:1px solid var(--line)}@media(max-width:750px){.navlinks{display:none}.grid{grid-template-columns:1fr}}</style></head><body><?php require_once __DIR__ . '/includes/public-nav.php'; ?><header class="hero"><div class="wrap"><div class="tag" style="color:#e5b5a9">Moving images · Nepal</div><h1>Disaster Documentary Archive</h1><p>Videos, documentaries, interviews, news reports, and recordings that help preserve how disasters were experienced, documented, and remembered.</p></div></header><main class="section"><div class="wrap"><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search documentaries, events, places..."><select name="type"><option value="">All media types</option><?php foreach(['DOCUMENTARY','INTERVIEW','RECORDING','NEWS_REPORT','OTHER'] as $item):?><option value="<?=e($item)?>" <?=$type===$item?'selected':''?>><?=e(str_replace('_',' ',$item))?></option><?php endforeach;?></select><button>Find recordings</button></form><div class="grid"><?php foreach($documentaries as $item):$embed=documentary_embed($item['video_url']);?><article class="card"><div class="media"><?php if($embed):?><iframe src="<?=e($embed)?>" title="<?=e($item['title'])?>" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe><?php elseif($item['thumbnail_url']):?><img src="<?=e($item['thumbnail_url'])?>" alt="<?=e($item['title'])?>"><?php endif;?></div><div class="card-body"><div class="tag"><?=e(str_replace('_',' ',$item['media_type']))?></div><h2><?=e($item['title'])?></h2><div class="meta"><?=e($item['location']?:'Nepal')?><?php if($item['event_date']):?> · <?=e($item['event_date'])?><?php endif;?><?php if($item['source_name']):?> · <?=e($item['source_name'])?><?php endif;?></div><p><?=e($item['description']??'')?></p><?php if(!$embed):?><a class="watch" href="<?=e($item['video_url'])?>" target="_blank" rel="noopener noreferrer">Open recording ↗</a><?php endif;?><?php if($item['story_title']):?><p class="meta">Related archive story: <?=e($item['story_title'])?></p><?php endif;?></div></article><?php endforeach;?><?php if(!$documentaries):?><div class="empty">No published documentaries match your search yet.</div><?php endif;?></div></div></main><?php require __DIR__.'/includes/public-footer.php'; ?></body></html>
